use crate::config::models::{ConfigRef, SetupConfig};

pub struct Language {
    pub name: &'static str,
    pub config: ConfigRef,
    /// Source files created by `acc setup`: (relative path, template body).
    pub files: &'static [(&'static str, &'static str)],
}

impl Language {
    /// Default `[setup]` section generated by `acc init` / `acc setup`.
    pub fn default_setup(&self) -> SetupConfig {
        SetupConfig {
            parent: None,
            dir: Some("${TASK_CHAR}".to_string()),
            file: Some(self.files.iter().map(|(p, _)| (*p).to_string()).collect()),
            template: None,
        }
    }
}

